@isTest private class CoreRuntimeEnumFamiliesEvidenceTest {
    @isTest static void enumFamiliesHaveDeterministicMembers() {
        loggingLevels();
        triggerOperations();
        jsonTokens();
        roundingModes();
        accessTypes();
        parentJobResults();
        quiddities();
    }

    private static void loggingLevels() {
        List<LoggingLevel> declared = new List<LoggingLevel>{LoggingLevel.NONE, LoggingLevel.INTERNAL, LoggingLevel.FINEST, LoggingLevel.FINER, LoggingLevel.FINE, LoggingLevel.DEBUG, LoggingLevel.INFO, LoggingLevel.WARN, LoggingLevel.ERROR};
        System.assertEquals(LoggingLevel.NONE, declared[0]);
        System.assertEquals(LoggingLevel.INTERNAL, declared[1]);
        System.assertEquals(LoggingLevel.FINEST, declared[2]);
        System.assertEquals(LoggingLevel.FINER, declared[3]);
        System.assertEquals(LoggingLevel.FINE, declared[4]);
        System.assertEquals(LoggingLevel.DEBUG, declared[5]);
        System.assertEquals(LoggingLevel.INFO, declared[6]);
        System.assertEquals(LoggingLevel.WARN, declared[7]);
        System.assertEquals(LoggingLevel.ERROR, declared[8]);
        List<LoggingLevel> values = LoggingLevel.values();
        System.assertEquals(9, values.size());
        for (Integer i = 0; i < values.size(); i++) System.assertEquals(declared[i], values[i]);
        System.assertEquals(LoggingLevel.INFO, LoggingLevel.valueOf('INFO'));
        System.assert(LoggingLevel.INFO.equals(declared[6]));
        System.assertEquals(LoggingLevel.INFO.hashCode(), declared[6].hashCode());
        System.assertEquals(6, LoggingLevel.INFO.ordinal());
    }

    private static void triggerOperations() {
        List<TriggerOperation> declared = new List<TriggerOperation>{TriggerOperation.BEFORE_INSERT, TriggerOperation.AFTER_INSERT, TriggerOperation.BEFORE_UPDATE, TriggerOperation.AFTER_UPDATE, TriggerOperation.BEFORE_DELETE, TriggerOperation.AFTER_DELETE, TriggerOperation.AFTER_UNDELETE};
        System.assertEquals(TriggerOperation.BEFORE_INSERT, declared[0]);
        System.assertEquals(TriggerOperation.AFTER_INSERT, declared[1]);
        System.assertEquals(TriggerOperation.BEFORE_UPDATE, declared[2]);
        System.assertEquals(TriggerOperation.AFTER_UPDATE, declared[3]);
        System.assertEquals(TriggerOperation.BEFORE_DELETE, declared[4]);
        System.assertEquals(TriggerOperation.AFTER_DELETE, declared[5]);
        System.assertEquals(TriggerOperation.AFTER_UNDELETE, declared[6]);
        List<TriggerOperation> values = TriggerOperation.values();
        System.assertEquals(7, values.size());
        for (Integer i = 0; i < values.size(); i++) System.assertEquals(declared[i], values[i]);
        System.assertEquals(TriggerOperation.BEFORE_INSERT, TriggerOperation.valueOf('BEFORE_INSERT'));
        System.assert(TriggerOperation.BEFORE_INSERT.equals(declared[0]));
        System.assertEquals(TriggerOperation.BEFORE_INSERT.hashCode(), declared[0].hashCode());
        System.assertEquals(0, TriggerOperation.BEFORE_INSERT.ordinal());
    }

    private static void jsonTokens() {
        List<JSONToken> declared = new List<JSONToken>{JSONToken.NOT_AVAILABLE, JSONToken.START_OBJECT, JSONToken.END_OBJECT, JSONToken.START_ARRAY, JSONToken.END_ARRAY, JSONToken.FIELD_NAME, JSONToken.VALUE_EMBEDDED_OBJECT, JSONToken.VALUE_STRING, JSONToken.VALUE_NUMBER_INT, JSONToken.VALUE_NUMBER_FLOAT, JSONToken.VALUE_TRUE, JSONToken.VALUE_FALSE, JSONToken.VALUE_NULL};
        System.assertEquals(JSONToken.NOT_AVAILABLE, declared[0]);
        System.assertEquals(JSONToken.START_OBJECT, declared[1]);
        System.assertEquals(JSONToken.END_OBJECT, declared[2]);
        System.assertEquals(JSONToken.START_ARRAY, declared[3]);
        System.assertEquals(JSONToken.END_ARRAY, declared[4]);
        System.assertEquals(JSONToken.FIELD_NAME, declared[5]);
        System.assertEquals(JSONToken.VALUE_EMBEDDED_OBJECT, declared[6]);
        System.assertEquals(JSONToken.VALUE_STRING, declared[7]);
        System.assertEquals(JSONToken.VALUE_NUMBER_INT, declared[8]);
        System.assertEquals(JSONToken.VALUE_NUMBER_FLOAT, declared[9]);
        System.assertEquals(JSONToken.VALUE_TRUE, declared[10]);
        System.assertEquals(JSONToken.VALUE_FALSE, declared[11]);
        System.assertEquals(JSONToken.VALUE_NULL, declared[12]);
        List<JSONToken> values = JSONToken.values();
        System.assertEquals(13, values.size());
        for (Integer i = 0; i < values.size(); i++) System.assertEquals(declared[i], values[i]);
        System.assertEquals(JSONToken.END_OBJECT, JSONToken.valueOf('END_OBJECT'));
        System.assert(JSONToken.END_OBJECT.equals(declared[2]));
        System.assertEquals(JSONToken.END_OBJECT.hashCode(), declared[2].hashCode());
        System.assertEquals(2, JSONToken.END_OBJECT.ordinal());
    }

    private static void roundingModes() {
        List<RoundingMode> declared = new List<RoundingMode>{RoundingMode.UP, RoundingMode.DOWN, RoundingMode.CEILING, RoundingMode.FLOOR, RoundingMode.HALF_UP, RoundingMode.HALF_DOWN, RoundingMode.HALF_EVEN, RoundingMode.UNNECESSARY};
