    private static void parentJobResults() {
        List<ParentJobResult> declared = new List<ParentJobResult>{ParentJobResult.SUCCESS, ParentJobResult.UNHANDLED_EXCEPTION};
        System.assertEquals(ParentJobResult.SUCCESS, declared[0]);
        System.assertEquals(ParentJobResult.UNHANDLED_EXCEPTION, declared[1]);
        List<ParentJobResult> values = ParentJobResult.values();
        System.assertEquals(2, values.size());
