        System.assertEquals(ParentJobResult.SUCCESS, ParentJobResult.valueOf('SUCCESS'));
        System.assert(ParentJobResult.SUCCESS.equals(declared[0]));
        System.assertEquals(ParentJobResult.SUCCESS.hashCode(), declared[0].hashCode());
        System.assertEquals(0, ParentJobResult.SUCCESS.ordinal());
    }

